toolArgs.file_text:
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    font-weight: 600;
    padding: 0.25rem 0.75rem;
    background: #e9ecef;
    border-radius: 4px;
}

.stat-overdue {
    background: #fee2e2;
    color: #dc2626;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.95rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    overflow-x: auto;
    padding-bottom: 1rem;
}

::deep .kanban-column {
    flex: 1;
    min-width: 280px;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
}

::deep .column-header h3 {
    margin: 0 0 0.75rem;
    font-size: 1.1rem;
}

::deep .column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

::deep .task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

::deep .task-card h4 {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .task-card .assignee {
    margin: 0 0 0.5rem;
    color: #6c757d;
    font-size: 0.85rem;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

::deep .priority-high {
    background: #fee2e2;
    color: #dc2626;
}

::deep .priority-medium {
    background: #fef3c7;
    color: #d97706;
}

::deep .priority-low {
    background: #d1fae5;
    color: #059669;
}

::deep .due-date {
    margin-left: 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-move:hover {
    background: #e9ecef;
}

::deep .btn-add {
    width: 100%;
    padding: 0.5rem;
    margin-top: 0.75rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    color: #6c757d;
}

::deep .btn-add:hover {
    background: #e9ecef;
}

::deep .add-task-form {
    margin-top: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .add-task-form input,
::deep .add-task-form select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    padding: 0.4rem 0.8rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-cancel {
    padding: 0.4rem 0.8rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.error-message {
    padding: 1rem;
    background: #fee2e2;
    border-radius: 8px;
    color: #dc2626;
}

.error-message button {
    margin-top: 0.5rem;
    padding: 0.4rem 0.8rem;
    background: #dc2626;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

